// BNY custody platform extracts. Only the BNY agent may import this module.
// Schemas follow data/DATA_DICTIONARY.md; /data is regenerated by script, never edited by hand.
import "server-only";
import { z } from "zod";
import {
  BNY_INSTRUCTION,
  CUSIP,
  DTC_REF,
  ISIN,
  LEI,
  PARTICIPANT,
  bnyTs,
  date,
  id,
  int,
  loadTables,
  nullable,
  num,
  text,
} from "./core";

const ACCOUNT = /^\d{4}-[A-Z]+-[A-Z]+$/;
const CURRENCY = z.enum(["USD", "EUR"]);

export const clientAccountSchema = z.object({
  account_id: id(ACCOUNT),
  client_legal_name: text(),
  client_short_code: text(),
  fund_name: text(),
  account_type: z.enum(["CUSTODY", "CASH"]),
  base_currency: CURRENCY,
  client_tier: int().pipe(z.number().int().min(1).max(3)),
  relationship_manager: text(),
  service_executive: text(),
  status: z.enum(["OPEN"]),
  opened_date: date(),
});

export const securityMasterSchema = z.object({
  bny_sec_id: id(/^BNYS\d{6}$/),
  isin: id(ISIN),
  cusip: id(CUSIP),
  ticker: nullable(text()),
  issuer_name: text(),
  asset_class: z.enum(["EQUITY", "ETF", "UST", "CORP_BOND"]),
  currency: z.enum(["USD"]),
  primary_exchange: z.enum(["NASDAQ", "NYSE", "OTC"]),
  settlement_cycle: z.enum(["T+1", "T+2"]),
  settlement_location: z.enum(["DTC", "FED"]),
  ref_price: nullable(num()),
  id_source: z.enum(["public", "synthetic"]),
  status: z.enum(["ACTIVE", "INACTIVE"]),
});

export const ssiCounterpartySchema = z.object({
  ssi_id: id(/^SSI-[A-Z]{2,4}-US-[A-Z]{2}-[A-Z0-9-]+$/),
  counterparty_name: text(),
  counterparty_lei: nullable(id(LEI)),
  market: text(),
  asset_class: z.enum(["EQUITY", "FIXED_INCOME"]),
  depository: text(),
  dtc_participant: id(PARTICIPANT),
  agent_bic: nullable(text()),
  effective_date: date(),
  end_date: nullable(date()),
  verified_by: nullable(text()),
  verification_date: nullable(date()),
  status: z.enum(["ACTIVE", "SUPERSEDED", "PENDING_VERIFICATION"]),
});

export const settlementInstructionSchema = z.object({
  instruction_id: id(BNY_INSTRUCTION),
  received_ts_et: bnyTs(),
  source_channel: z.enum(["SWIFT_MT541", "SWIFT_MT543", "CTM", "PORTAL"]),
  client_account_id: id(ACCOUNT),
  client_ref: text(),
  direction: z.enum(["RVP", "DVP"]),
  isin: id(ISIN),
  quantity: num(),
  price: num(),
  settlement_amount: num(),
  currency: z.enum(["USD"]),
  trade_date: date(),
  settle_date: date(),
  counterparty_name: text(),
  cpty_dtc_participant: nullable(id(PARTICIPANT)),
  settlement_location: z.enum(["DTC", "FED"]),
  amends_instruction_id: nullable(id(BNY_INSTRUCTION)),
  /** The DTC delivery this instruction settles against, once instructed there. */
  dtc_reference: nullable(id(DTC_REF)),
  status: z.enum([
    "RECEIVED",
    "IN_REPAIR",
    "ENRICHED",
    "SENT_TO_DTC",
    "SENT_TO_FED",
    "MATCHED",
    "SETTLED",
    "PENDING_SETTLEMENT",
    "CANCELLED",
  ]),
  status_ts_et: bnyTs(),
});

export const repairQueueSchema = z.object({
  repair_id: id(/^RQ-\d{8}-\d{4}$/),
  instruction_id: id(BNY_INSTRUCTION),
  opened_ts_et: bnyTs(),
  repair_reason: z.enum([
    "MISSING_SEC_ID",
    "MISSING_CPTY_PARTICIPANT",
    "QTY_PRICE_MISMATCH",
    "INVALID_SSI",
    "MISSING_SETTLE_DATE",
    "DUPLICATE_SUSPECT",
  ]),
  routed_to: z.enum(["DIGITAL_EMPLOYEE", "HUMAN"]),
  priority_score: num().pipe(z.number().min(0).max(100)),
  cutoff_ts_et: bnyTs(),
  trade_value_usd: num(),
  assigned_to: nullable(text()),
  resolution: nullable(
    z.enum([
      "ENRICHED_FROM_REFDATA",
      "REJECTED_NO_REFDATA_MATCH",
      "CORRECTED_PER_CLIENT",
      "ENRICHED_FROM_SSI",
      "CANCELLED_DUPLICATE",
      "CONFIRMED_WITH_CLIENT",
    ]),
  ),
  resolved_ts_et: nullable(bnyTs()),
  verified_by: nullable(text()),
  comments: nullable(text()),
});

export const positionSchema = z.object({
  as_of_date: date(),
  account_id: id(ACCOUNT),
  isin: id(ISIN),
  quantity: num(),
  pending_receipts: num(),
  pending_deliveries: num(),
  market_value_usd: num(),
});

export const cashLedgerSchema = z.object({
  entry_id: id(/^CL-/),
  account_id: id(ACCOUNT),
  value_date: date(),
  amount: num(),
  currency: z.enum(["USD"]),
  entry_type: z.enum(["TRADE_SETTLEMENT"]),
  related_instruction_id: id(BNY_INSTRUCTION),
  status: z.enum(["POSTED"]),
});

export const failExceptionSchema = z.object({
  exception_id: id(/^EXC-\d{8}-\d{4}$/),
  instruction_id: id(BNY_INSTRUCTION),
  dtc_reference: nullable(id(DTC_REF)),
  detected_ts_et: bnyTs(),
  fail_reason: z.enum([
    "LACK_OF_SECURITIES",
    "SSI_MISMATCH",
    "LATE_AFFIRMATION",
    "DK_QTY_MISMATCH",
    "ON_HOLD",
    "CASH_SHORTFALL",
  ]),
  counterparty_name: text(),
  days_outstanding: nullable(int()),
  status: z.enum(["OPEN", "RESOLVED"]),
  owner: nullable(text()),
  resolution_notes: nullable(text()),
});

export const clientInquirySchema = z.object({
  inquiry_id: id(/^INQ-\d{8}-\d{5}$/),
  received_ts_et: bnyTs(),
  client_short_code: text(),
  channel: z.enum(["EMAIL", "PORTAL", "PHONE"]),
  intent: z.enum(["TRANSACTION_STATUS", "CORP_ACTION", "TAX", "OTHER"]),
  related_instruction_id: nullable(id(BNY_INSTRUCTION)),
  draft_by: z.enum(["DISC", "HUMAN"]),
  response_seconds: int(),
  reviewed_by: text(),
  status: z.enum(["CLOSED"]),
});

const schemas = {
  settlement_instructions: settlementInstructionSchema,
  repair_queue: repairQueueSchema,
  fails_exceptions: failExceptionSchema,
  positions: positionSchema,
  cash_ledger: cashLedgerSchema,
  client_inquiries: clientInquirySchema,
  client_accounts: clientAccountSchema,
  securities_master: securityMasterSchema,
  ssi_counterparties: ssiCounterpartySchema,
};

export type SettlementInstruction = z.output<typeof settlementInstructionSchema>;
export type RepairItem = z.output<typeof repairQueueSchema>;
export type FailException = z.output<typeof failExceptionSchema>;
export type Position = z.output<typeof positionSchema>;
export type CashLedgerEntry = z.output<typeof cashLedgerSchema>;
export type ClientInquiry = z.output<typeof clientInquirySchema>;
export type ClientAccount = z.output<typeof clientAccountSchema>;
export type Security = z.output<typeof securityMasterSchema>;
export type SsiCounterparty = z.output<typeof ssiCounterpartySchema>;
export type BnyData = ReturnType<typeof loadBny>;

let cache: ReturnType<typeof load> | undefined;
const load = () => loadTables("bny", schemas);

/** All BNY tables, parsed once and cached in memory. */
export function loadBny() {
  return (cache ??= load());
}
